mapper.select:
SELECT FROM comment c JOIN `user` u ON u.id = c.author_id LEFT JOIN `user` ru ON ru.id = c.reply_to_user_id WHERE c.video_id = #{videoId} AND c.root_id IS NULL AND c.status = 1 AND c.deleted_at IS NULL
AND ( c.is_pinned < (SELECT is_pinned FROM comment WHERE id=#{cursorId}) OR (c.is_pinned = (SELECT is_pinned FROM comment WHERE id=#{cursorId}) AND
(c.like_count < (SELECT like_count FROM comment WHERE id=#{cursorId}) OR (c.like_count = (SELECT like_count FROM comment WHERE id=#{cursorId}) AND c.id < #{cursorId}))
c.id < #{cursorId}
) )
ORDER BY c.is_pinned DESC, c.like_count DESC, c.id DESC LIMIT #{limit}

SELECT FROM comment c JOIN `user` u ON u.id = c.author_id LEFT JOIN `user` ru ON ru.id = c.reply_to_user_id WHERE c.root_id IN
#{rid}
AND c.status = 1 AND c.deleted_at IS NULL ORDER BY c.id ASC

SELECT FROM comment c JOIN `user` u ON u.id=c.author_id LEFT JOIN `user` ru ON ru.id=c.reply_to_user_id WHERE c.post_id=#{postId} AND c.root_id IS NULL AND c.status=1 AND c.deleted_at IS NULL
AND (c.like_count < COALESCE((SELECT like_count FROM comment WHERE id=#{cursorId}),0) OR (c.like_count=COALESCE((SELECT like_count FROM comment WHERE id=#{cursorId}),0) AND c.id < #{cursorId}))
AND c.id < #{cursorId}
ORDER BY c.like_count DESC, c.id DESC LIMIT #{limit}
